  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {
101→        self.project.is_some()
102→    }
103→}
104→
105→/// Find the project root by walking up from current directory.
106→///
107→/// Looks for:
108→/// 1. `.bivvy` directory (primary indicator)
109→/// 2. `.git` directory (fallback)
110→///
111→/// # Returns
112→///
113→/// The path to the project root, or None if not found.
114→pub fn find_project_root(start: &Path) -> Option<PathBuf> {
115→    let mut current = start.to_path_buf();
116→
117→    loop {
118→        // Check for .bivvy directory
119→        if current.join(".bivvy").is_dir() {
120→            return Some(current);
121→        }
122→
123→        // Check for .git directory (fallback)
124→        if current.join(".git").exists() {
125→            return Some(current);
126→        }
127→
128→        // Move up one directory
129→        if !current.pop() {
130→            return None;
131→        }
132→    }
133→}
134→
135→/// Load a single config file and parse it into BivvyConfig.
136→///
137→/// # Errors
138→///
139→/// Returns `ConfigNotFound` if the file doesn't exist.
140→/// Returns `ConfigParseError` if the YAML is invalid.
141→pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
142→    let content = fs::read_to_string(path).map_err(|e| {
143→        if e.kind() == std::io::ErrorKind::NotFound {
144→            BivvyError::ConfigNotFound {
145→                path: path.to_path_buf(),
146→            }
147→        } else {
148→            BivvyError::Io(e)
149→        }
150→    })?;

  1→//! Configuration validation rules.
  2→//!
  3→//! This module validates configuration for correctness:
  4→//! - Steps must have either template or command
  5→//! - depends_on must reference existing steps
  6→//! - Workflows must reference existing steps
  7→//! - No circular dependencies allowed
  8→
  9→use crate::config::schema::BivvyConfig;
 10→use crate::error::{BivvyError, Result};
 11→use std::collections::HashSet;
 12→
 13→/// Validation error with context.
 14→#[derive(Debug, Clone)]
 15→pub struct ValidationError {
 16→    /// Rule identifier
 17→    pub rule: String,
 18→    /// Human-readable error message
 19→    pub message: String,
 20→    /// Step name if error is step-specific
 21→    pub step: Option<String>,
 22→    /// Workflow name if error is workflow-specific
 23→    pub workflow: Option<String>,
 24→}
 25→
 26→/// Validate a configuration and return all errors.
 27→///
 28→/// This function collects all validation errors rather than stopping
 29→/// at the first one, allowing users to fix multiple issues at once.
 30→pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
 31→    let mut errors = Vec::new();
 32→
 33→    errors.extend(validate_steps(config));
 34→    errors.extend(validate_workflows(config));
 35→    errors.extend(validate_dependencies(config));
 36→
 37→    errors
 38→}
 39→
 40→/// Validate step definitions.
 41→fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
 42→    let mut errors = Vec::new();
 43→
 44→    for (name, step) in &config.steps {
 45→        // Step must have either template or command
 46→        if step.template.is_none() && step.command.is_none() {
 47→            errors.push(ValidationError {
 48→                rule: "missing-command".to_string(),
 49→                message: format!("Step '{}' must have either 'template' or 'command'", name),
 50→                step: Some(name.clone()),
 51→                workflow: None,
 52→            });
 53→        }
 54→
 55→        // Validate depends_on references
 56→        for dep in &step.depends_on {
 57→            if !config.steps.contains_key(dep) {
 58→                errors.push(ValidationError {
 59→                    rule: "unknown-step".to_string(),
 60→                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
 61→                    step: Some(name.clone()),
 62→                    workflow: None,
 63→                });
 64→            }
 65→        }
 66→    }
 67→
 68→    errors
 69→}
 70→
 71→/// Validate workflow definitions.
 72→fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
 73→    let mut errors = Vec::new();
 74→
 75→    for (name, workflow) in &config.workflows {
 76→        // Validate step references
 77→        for step_name in &workflow.steps {
 78→            if !config.steps.contains_key(step_name) {
 79→                errors.push(ValidationError {
 80→                    rule: "unknown-workflow-step".to_string(),
 81→                    message: format!(
 82→                        "Workflow '{}' references step '{}' which does not exist",
 83→                        name, step_name
 84→                    ),
 85→                    step: None,
 86→                    workflow: Some(name.clone()),
 87→                });
 88→            }
 89→        }
 90→
 91→        // Validate override references
 92→        for step_name in workflow.overrides.keys() {
 93→            if !workflow.steps.contains(step_name) {
 94→                errors.push(ValidationError {
 95→                    rule: "unknown-override-step".to_string(),
 96→                    message: format!(
 97→                        "Workflow '{}' has override for '{}' which is not in the workflow",
 98→                        name, step_name
 99→                    ),
100→                    step: None,

150→    })?;
