        assert!(matches!(
            config.vars.get("app_name"),
            Some(VarDefinition::Static(_))
        ));
        assert!(matches!(
            config.vars.get("version"),
            Some(VarDefinition::Computed { .. })
        ));
    }

    #[test]
    fn empty_vars_defaults() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert!(config.vars.is_empty());
    }

    #[test]
    fn serialize_omits_empty_vars() {
        let config: BivvyConfig = serde_yaml::from_str("app_name: test").unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(!yaml.contains("vars"), "empty vars should be omitted");
    }

    // --- Precondition parsing tests ---

    #[test]
    fn parses_precondition_command_succeeds() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: command_succeeds
      command: "test $(git branch --show-current) = main"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        assert!(matches!(
            step.precondition,
            Some(CompletedCheck::CommandSucceeds { .. })
        ));
    }

    #[test]
    fn parses_precondition_all() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: all
      checks:
        - type: command_succeeds
          command: "test $(git branch --show-current) = main"
        - type: command_succeeds
          command: "git diff --quiet"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        if let Some(CompletedCheck::All { checks }) = &step.precondition {
            assert_eq!(checks.len(), 2);
        } else {
            panic!("Expected All precondition");
        }
    }

    #[test]
    fn precondition_defaults_none() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.precondition.is_none());
    }

    #[test]
    fn serialize_omits_none_precondition() {
        let config: BivvyConfig = serde_yaml::from_str(
            r#"
steps:
  hello:
    command: "echo hello"
"#,
        )
        .unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(
            !yaml.contains("precondition"),
            "None precondition should be omitted"
        );
    }

    #[test]
    fn environment_override_bare_null_parses_as_none() {
        let yaml = "command:";
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert!(o.command.is_none());
    }

    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }

    #[test]
    fn unknown_top_level_field_is_rejected() {
        let yaml = r#"
app_name: "MyApp"
stesp:
  hello:
    command: "echo hello"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown top-level field 'stesp' should be rejected");
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("unknown field"),
            "error should mention 'unknown field', got: {}",
            err
        );
    }

    #[test]
    fn unknown_settings_field_is_rejected() {
        let yaml = r#"
settings:
  defualt_output: quiet
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown settings field 'defualt_output' should be rejected");
    }

    #[test]
    fn unknown_step_field_is_rejected() {
        let yaml = r#"
steps:
  hello:
    commnad: "echo hello"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown step field 'commnad' should be rejected");
    }

    #[test]
    fn unknown_workflow_field_is_rejected() {
        let yaml = r#"
workflows:
  default:
    stpes: [hello]
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow field 'stpes' should be rejected");
    }
}

